//! Audio bed synthesis and mixing.
//!
//! The BGM and every sound effect are generated by this code — no sample
//! files, no external tools. Narration is a reserved slot: if the project
//! points at a PCM WAV file it is decoded and mixed in; otherwise the slot
//! stays silent.

use media_codec::MediaLibrary;
use media_scene::AudioSpec;
use media_types::Error;
use media_types::SAMPLE_RATE;
use media_types::hash;

/// Sample rate shared by the whole pipeline.

/// Builds the full audio bed: synthesized BGM and effects, the reserved
/// narration slot, and every imported audio clip placed on the timeline.
#[must_use]
pub fn build_audio(spec: Option<&AudioSpec>, duration_seconds: f64, fps: u32, media: &mut MediaLibrary) -> Vec<i16> {
    let frames = (duration_seconds * SAMPLE_RATE as f64).ceil() as usize;
    let mut buf = vec![0f32; frames * 2];

    if let Some(spec) = spec {
        if let Some(bgm) = &spec.bgm {
            synth_pad(&mut buf, bgm.volume);
            synth_plucks(&mut buf, bgm.volume * 0.5);
        }
        for sfx in &spec.sfx {
            let seconds = sfx.at as f64 / fps as f64;
            match sfx.kind.as_str() {
                "whoosh" => whoosh(&mut buf, seconds, sfx.volume),
                "tick" => tick(&mut buf, seconds, sfx.volume),
                "impact" => impact(&mut buf, seconds, sfx.volume),
                "riser" => riser(&mut buf, seconds, sfx.volume),
                "glitch" => glitch(&mut buf, seconds, sfx.volume),
                "sub" => sub_drop(&mut buf, seconds, sfx.volume),
                _ => {}
            }
        }
        if let Some(narration) = &spec.narration {
            mix_wav(&mut buf, &narration.wav, narration.delay_frames, narration.volume, fps);
        }
        for clip in &spec.clips {
            // A missing or undecodable import must not abort the render: the
            // clip stays silent and the rest of the film still compiles.
            let Ok(samples) = media.audio_pcm(&clip.src) else {
                continue;
            };
            let start = (clip.at as f64 / fps as f64 * SAMPLE_RATE as f64) as usize;
            let offset = (clip.offset_frames as f64 / fps as f64 * SAMPLE_RATE as f64) as usize;
            let limit = clip.dur.map(|d| (d as f64 / fps as f64 * SAMPLE_RATE as f64) as usize).unwrap_or(usize::MAX);
            let total = frames_len(&buf);
            for i in 0..limit {
                let Some(sample) = samples.get(offset + i) else {
                    break;
                };
                let Some(at) = start.checked_add(i) else {
                    break;
                };
                if at >= total {
                    break;
                }
                buf[at * 2] += sample[0] * clip.volume;
                buf[at * 2 + 1] += sample[1] * clip.volume;
            }
        }
    }

    buf.into_iter().map(|s| (s.clamp(-1.0, 1.0) * 32767.0) as i16).collect()
}

fn frames_len(buf: &[f32]) -> usize {
    buf.len() / 2
}

/// Slow chord pad: four chords cycling, two detuned partials each.
fn synth_pad(buf: &mut [f32], volume: f32) {
    // A minor bed: Am, F, C, G — root frequencies.
    let chords = [[110.0, 164.81, 220.0], [87.31, 130.81, 174.61], [130.81, 164.81, 196.0], [98.0, 123.47, 146.83]];
    let chord_seconds = 8.0;
    for i in 0..frames_len(buf) {
        let t = i as f64 / SAMPLE_RATE as f64;
        let chord = &chords[((t / chord_seconds) as usize) % chords.len()];
        let phase_in_chord = (t % chord_seconds) / chord_seconds;
        let env = (phase_in_chord * std::f64::consts::PI).sin().powf(0.6);
        let mut s = 0.0f64;
        for f in chord {
            let w = *f * t * std::f64::consts::TAU;
            s += w.sin() * 0.5 + (w * 2.0).sin() * 0.12;
            let detuned = (*f * 1.003) * t * std::f64::consts::TAU;
            s += detuned.sin() * 0.35;
        }
        let value = (s / (chord.len() as f64 * 1.2)) * env * volume as f64;
        // Gentle stereo width via alternating polarity of the detune.
        buf[i * 2] += value as f32;
        buf[i * 2 + 1] += value as f32 * 0.92;
    }
}

/// Sparse pentatonic plucks seeded deterministically.
fn synth_plucks(buf: &mut [f32], volume: f32) {
    let scale = [440.0, 523.25, 587.33, 659.25, 783.99];
    let total = frames_len(buf);
    let mut slot = 0usize;
    let mut cursor = (SAMPLE_RATE as usize) * 3; // start after 3s
    while cursor < total {
        let seed = hash(slot as u32);
        let note = scale[(seed % scale.len() as u32) as usize];
        let decay_seconds = 1.6;
        let len = ((decay_seconds * SAMPLE_RATE as f64) as usize).min(total - cursor);
        for i in 0..len {
            let t = i as f64 / SAMPLE_RATE as f64;
            let env = (-t * 3.2).exp();
            let s = (note * t * std::f64::consts::TAU).sin() * 0.7 + (note * 2.0 * t * std::f64::consts::TAU).sin() * 0.2;
            let v = (s * env * volume as f64 * 0.5) as f32;
            buf[(cursor + i) * 2] += v;
            buf[(cursor + i) * 2 + 1] += v * 0.9;
        }
        slot += 1;
        let gap = 2.0 + (hash(slot as u32 * 7 + 13) % 40) as f64 / 10.0;
        cursor += (gap * SAMPLE_RATE as f64) as usize;
    }
}

/// Filtered noise sweep for scene transitions.
fn whoosh(buf: &mut [f32], at_seconds: f64, volume: f32) {
    let start = (at_seconds * SAMPLE_RATE as f64) as usize;
    let len = (0.55 * SAMPLE_RATE as f64) as usize;
    let total = frames_len(buf);
    let mut seed = (start as u32) | 0x9e37;
    let mut low = 0.0f32;
    for i in 0..len {
        if start + i >= total {
            break;
        }
        let t = i as f32 / len as f32;
        let env = (t * std::f32::consts::PI).sin().powf(1.5);
        seed = hash(seed);
        let noise = (seed as f32 / u32::MAX as f32) * 2.0 - 1.0;
        low += (noise - low) * (0.02 + t * 0.25);
        let v = low * env * volume;
        buf[(start + i) * 2] += v;
        buf[(start + i) * 2 + 1] += v * 0.95;
    }
}

/// Short high blip for counters and list ticks.
fn tick(buf: &mut [f32], at_seconds: f64, volume: f32) {
    let start = (at_seconds * SAMPLE_RATE as f64) as usize;
    let len = (0.06 * SAMPLE_RATE as f64) as usize;
    let total = frames_len(buf);
    for i in 0..len {
        if start + i >= total {
            break;
        }
        let t = i as f64 / SAMPLE_RATE as f64;
        let env = (-t * 60.0).exp();
        let s = (1320.0 * t * std::f64::consts::TAU).sin() * env * volume as f64 * 0.5;
        buf[(start + i) * 2] += s as f32;
        buf[(start + i) * 2 + 1] += s as f32;
    }
}

/// Low thud for emphasis moments.
fn impact(buf: &mut [f32], at_seconds: f64, volume: f32) {
    let start = (at_seconds * SAMPLE_RATE as f64) as usize;
    let len = (0.35 * SAMPLE_RATE as f64) as usize;
    let total = frames_len(buf);
    for i in 0..len {
        if start + i >= total {
            break;
        }
        let t = i as f64 / SAMPLE_RATE as f64;
        let env = (-t * 9.0).exp();
        let s = (72.0 * t * std::f64::consts::TAU).sin() * env * volume as f64;
        buf[(start + i) * 2] += s as f32;
        buf[(start + i) * 2 + 1] += s as f32;
    }
}

/// Rising filtered noise, used to build tension into a cut.
fn riser(buf: &mut [f32], at_seconds: f64, volume: f32) {
    let start = (at_seconds * SAMPLE_RATE as f64) as usize;
    let len = (1.6 * SAMPLE_RATE as f64) as usize;
    let total = frames_len(buf);
    let mut seed = (start as u32) | 0x5f37;
    let mut low = 0.0f32;
    for i in 0..len {
        if start + i >= total {
            break;
        }
        let t = i as f32 / len as f32;
        seed = hash(seed);
        let noise = (seed as f32 / u32::MAX as f32) * 2.0 - 1.0;
        // The filter opens up as the riser climbs.
        low += (noise - low) * (0.01 + t * t * 0.5);
        let env = t * t;
        let v = low * env * volume;
        buf[(start + i) * 2] += v;
        buf[(start + i) * 2 + 1] += v * 0.9;
    }
}

/// Short bit-crushed burst for a hard cut.
fn glitch(buf: &mut [f32], at_seconds: f64, volume: f32) {
    let start = (at_seconds * SAMPLE_RATE as f64) as usize;
    let len = (0.14 * SAMPLE_RATE as f64) as usize;
    let total = frames_len(buf);
    for i in 0..len {
        if start + i >= total {
            break;
        }
        let t = i as f32 / SAMPLE_RATE as f32;
        let env = (1.0 - i as f32 / len as f32).powi(2);
        // Quantize a square wave to a few levels for the crushed edge.
        let square: f32 = if (t * 940.0).fract() < 0.5 { 1.0 } else { -1.0 };
        let stepped = (square * 3.0).round() / 3.0;
        let v = stepped * env * volume;
        buf[(start + i) * 2] += v;
        buf[(start + i) * 2 + 1] += v * 0.85;
    }
}

/// Sub-bass drop that lands under a cut.
fn sub_drop(buf: &mut [f32], at_seconds: f64, volume: f32) {
    let start = (at_seconds * SAMPLE_RATE as f64) as usize;
    let len = (0.9 * SAMPLE_RATE as f64) as usize;
    let total = frames_len(buf);
    for i in 0..len {
        if start + i >= total {
            break;
        }
        let t = i as f64 / SAMPLE_RATE as f64;
        let env = (-t * 3.4).exp();
        let freq = 92.0 - t * 46.0;
        let s = (freq * t * std::f64::consts::TAU).sin() * env * volume as f64;
        buf[(start + i) * 2] += s as f32;
        buf[(start + i) * 2 + 1] += s as f32;
    }
}

/// Decodes a PCM16 WAV file and mixes it at the given frame offset.
fn mix_wav(buf: &mut [f32], path: &str, delay_frames: u32, volume: f32, fps: u32) {
    let Ok(bytes) = std::fs::read(path) else {
        // The narration slot is optional input; a missing file stays silent.
        return;
    };
    let Some(samples) = parse_wav_pcm16(&bytes) else {
        return;
    };
    let start = (delay_frames as f64 / fps as f64 * SAMPLE_RATE as f64) as usize;
    let total = frames_len(buf);
    for (i, frame) in samples.iter().enumerate() {
        let at = start + i;
        if at >= total {
            break;
        }
        buf[at * 2] += frame[0] * volume;
        buf[at * 2 + 1] += frame[1] * volume;
    }
}

/// Minimal RIFF reader: PCM16 in, interleaved stereo f32 out (mono is widened).
pub fn parse_wav_pcm16(bytes: &[u8]) -> Option<Vec<[f32; 2]>> {
    let read_u32 = |i: usize| -> Option<u32> { Some(u32::from_le_bytes(bytes[i..i + 4].try_into().ok()?)) };
    let read_u16 = |i: usize| -> Option<u16> { Some(u16::from_le_bytes(bytes[i..i + 2].try_into().ok()?)) };
    if bytes.len() < 44 || &bytes[0..4] != b"RIFF" || &bytes[8..12] != b"WAVE" {
        return None;
    }
    let mut pos = 12usize;
    let mut channels = 1u16;
    let mut bits = 16u16;
    let mut data_start = 0usize;
    let mut data_len = 0usize;
    while pos + 8 <= bytes.len() {
        let id = &bytes[pos..pos + 4];
        let size = read_u32(pos + 4)? as usize;
        match id {
            b"fmt " => {
                channels = read_u16(pos + 10)?;
                bits = read_u16(pos + 22)?;
            }
            b"data" => {
                data_start = pos + 8;
                data_len = size.min(bytes.len() - data_start);
            }
            _ => {}
        }
        pos += 8 + size + (size % 2);
    }
    if bits != 16 || data_len == 0 || channels == 0 {
        return None;
    }
    let frame_bytes = channels as usize * 2;
    let frames = data_len / frame_bytes;
    let mut out = Vec::with_capacity(frames);
    for f in 0..frames {
        let base = data_start + f * frame_bytes;
        let left = i16::from_le_bytes(bytes[base..base + 2].try_into().ok()?) as f32 / 32768.0;
        let right =
            if channels >= 2 { i16::from_le_bytes(bytes[base + 2..base + 4].try_into().ok()?) as f32 / 32768.0 } else { left };
        out.push([left, right]);
    }
    Some(out)
}

/// Writes an interleaved s16 stereo buffer as a PCM16 WAV file (debug aid and
/// the format the narration slot expects).
pub fn write_wav(path: &str, samples: &[i16]) -> Result<(), Error> {
    let data_bytes = samples.len() * 2;
    let mut out: Vec<u8> = Vec::with_capacity(44 + data_bytes);
    out.extend_from_slice(b"RIFF");
    out.extend_from_slice(&((36 + data_bytes) as u32).to_le_bytes());
    out.extend_from_slice(b"WAVE");
    out.extend_from_slice(b"fmt ");
    out.extend_from_slice(&16u32.to_le_bytes());
    out.extend_from_slice(&1u16.to_le_bytes());
    out.extend_from_slice(&2u16.to_le_bytes());
    out.extend_from_slice(&SAMPLE_RATE.to_le_bytes());
    out.extend_from_slice(&(SAMPLE_RATE * 4).to_le_bytes());
    out.extend_from_slice(&4u16.to_le_bytes());
    out.extend_from_slice(&16u16.to_le_bytes());
    out.extend_from_slice(b"data");
    out.extend_from_slice(&(data_bytes as u32).to_le_bytes());
    for s in samples {
        out.extend_from_slice(&s.to_le_bytes());
    }
    std::fs::write(path, out)?;
    Ok(())
}
